import { Effect } from "effect"

// These should trigger floatingEffect diagnostic (code 377001)
Effect.succeed("floating")
Effect.never
Effect.void
Effect.fail("error")

// These should NOT trigger (assigned to variable)
const ok = Effect.succeed(1)
const x = Effect.void

// These should NOT trigger (assignment expressions)
let logicalAssignment: Effect.Effect<void, never, never>
logicalAssignment = Effect.void
logicalAssignment ??= Effect.void
logicalAssignment ||= Effect.void
logicalAssignment &&= Effect.void

// Property assignment should NOT trigger
class MyClass {
  boot: Effect.Effect<void, never, never>
  constructor() {
    this.boot = Effect.void
  }
}

import { Data, Effect } from "effect"

class ExampleError extends Data.TaggedError("ExampleError")<{}> {}

const Controller = AbortController

export const controllerInGen = Effect.gen(function*() {
  const direct = new AbortController()
  const aliased = new Controller()
  return [direct, aliased]
})

export const controllerInFn = Effect.fn("controllerInFn")(function*() {
  return new AbortController()
})

export const controllerWithFinalizer = Effect.gen(function*() {
  const controller = new AbortController()
  yield* Effect.addFinalizer(() => Effect.sync(() => controller.abort()))
  return controller.signal
})

// Non-generator Effect thunks are outside this rule's scope.
export const controllerInSync = Effect.sync(() => new AbortController())
export const controllerInPromise = Effect.promise(async () => new AbortController())
export const controllerInCallback = Effect.callback<AbortController>((resume) => {
  const controller = new AbortController()
  resume(Effect.succeed(controller))
})
export const controllerInSuspend = Effect.suspend(() => Effect.succeed(new AbortController()))
export const controllerInTry = Effect.try(() => new AbortController())
export const controllerInTryObject = Effect.try({
  try: () => new AbortController(),
  catch: () => new ExampleError()
})
export const controllerInTryPromise = Effect.tryPromise(async () => new AbortController())
export const controllerInTryPromiseObject = Effect.tryPromise({
  try: async () => new AbortController(),
  catch: () => new ExampleError()
})

new AbortController()
export const controllerOutsideEffect = () => new AbortController()

export const controllerInNestedFunction = Effect.gen(function*() {
  return () => new AbortController()
})

export const shadowedController = Effect.gen(function*() {
  class AbortController {
    readonly signal = "local"
  }
  return new AbortController()
})

// @effect-v4
/// <reference lib="esnext.disposable" />
import { Effect } from "effect"
import { acquireRelease } from "effect/Effect"

declare const acquireSync: Effect.Effect<Disposable>
declare const acquireAsync: Effect.Effect<AsyncDisposable>

// Should trigger for the synchronous disposal protocol.
export const syncDisposable = Effect.acquireRelease(
  acquireSync,
  (resource) => Effect.sync(() => resource[Symbol.dispose]())
)

// Should trigger for the asynchronous disposal protocol with an unused exit.
export const asyncDisposable = Effect.acquireRelease(
  acquireAsync,
  function(resource, _exit) {
    return Effect.promise(function() {
      return resource[Symbol.asyncDispose]()
    })
  }
)

// Should trigger through an Effect namespace alias.
const Fx = Effect
export const aliasedModule = Fx.acquireRelease(
  acquireSync,
  (resource) => Fx.sync(() => resource[Symbol.dispose]())
)

// Should diagnose a named import and fix its usage through the Effect module.
export const namedImport = acquireRelease(
  acquireAsync,
  (resource) => Effect.promise(async () => resource[Symbol.asyncDispose]())
)

declare const acquireBoth: Effect.Effect<Disposable | (Disposable & AsyncDisposable)>
export const disposableUnion = Effect.acquireRelease(
  acquireBoth,
  (resource) => Effect.sync(() => resource[Symbol.dispose]())
)

// Should not trigger when a named method happens to implement the protocol.
interface ManagedLike extends AsyncDisposable {
  dispose(): Promise<void>
}
declare const acquireManaged: Effect.Effect<ManagedLike>
export const namedDispose = Effect.acquireRelease(
  acquireManaged,
  (resource) => Effect.promise(() => resource.dispose())
)

// Should not trigger for a named cleanup method without a disposal protocol.
declare const acquireCloseable: Effect.Effect<{ close(): void }>
export const namedClose = Effect.acquireRelease(
  acquireCloseable,
  (resource) => Effect.sync(() => resource.close())
)

// Should not trigger when the release contains extra behavior.
export const extraCleanup = Effect.acquireRelease(
  acquireSync,
  (resource) => Effect.sync(() => {
    resource[Symbol.dispose]()
    console.log("disposed")
  })
)

// Should not trigger when the release depends on the exit.
export const exitAware = Effect.acquireRelease(
  acquireSync,
  (resource, exit) => Effect.sync(() => {
    console.log(exit)
    resource[Symbol.dispose]()
  })
)

// Should not trigger when the wrappers do not implement the protocol correctly.
export const unawaitedAsyncDispose = Effect.acquireRelease(
  acquireAsync,
  (resource) => Effect.sync(() => resource[Symbol.asyncDispose]())
)

// Should not trigger when acquireRelease options carry extra semantics.
export const interruptible = Effect.acquireRelease(
  acquireSync,
  (resource) => Effect.sync(() => resource[Symbol.dispose]()),
  { interruptible: true }
)

// Should not trigger for imprecise success types.
declare const acquireAny: Effect.Effect<any>
export const imprecise = Effect.acquireRelease(
  acquireAny,
  (resource) => Effect.sync(() => resource[Symbol.dispose]())
)

// Should not trigger for an unrelated API with the same shape.
const unrelated = {
  acquireRelease: <A>(acquire: Effect.Effect<A>, release: (value: A) => Effect.Effect<unknown>) =>
    Effect.acquireRelease(acquire, release)
}
export const unrelatedCall = unrelated.acquireRelease(
  acquireSync,
  (resource) => Effect.sync(() => resource[Symbol.dispose]())
)

// @effect-v4
import { Effect, pipe } from "effect"

declare const values: ReadonlyArray<number>
declare const effectful: (value: number, index: number) => Effect.Effect<string>

// Should trigger without options.
export const direct = Effect.all(values.map(effectful))

// Should trigger with a fallback fix when Effect.all is hidden behind a const alias.
const allAlias = Effect.all
export const aliasedAll = allAlias(values.map(effectful))

// Should trigger and carry compatible options through to Effect.forEach.
export const withOptions = Effect.all(
  values.map((value, index) => Effect.succeed(`${index}:${value}`)),
  { concurrency: 2, discard: true }
)

// The suggested replacements must type-check with the same receiver, callback,
// index parameter, and options.
export const expectedDirect = Effect.forEach(values, effectful)
export const expectedWithOptions = Effect.forEach(
  values,
  (value, index) => Effect.succeed(`${index}:${value}`),
  { concurrency: 2, discard: true }
)

// Should trigger, but should not offer an unsafe fix that drops the map generic.
export const explicitMapGeneric = Effect.all(
  values.map<Effect.Effect<string>>((value) => Effect.succeed(String(value)))
)

// Should not trigger when Effect.all mode changes the result semantics.
export const resultMode = Effect.all(values.map(effectful), { mode: "result" })
const resultOptions = { mode: "result" as const, concurrency: 2 }
export const resultModeFromOptions = Effect.all(values.map(effectful), resultOptions)

// Should not trigger for a non-array receiver with a map method.
declare const recordMapper: {
  readonly [index: number]: number
  map<B>(f: (value: number) => B): ReadonlyArray<B>
}
export const record = Effect.all(recordMapper.map((value) => Effect.succeed(value)))

// Should not trigger when the callback does not return an Effect.
// @ts-expect-error Effect.all requires Effect values
export const plainValues = Effect.all(values.map((value) => value + 1))

// Should trigger for data-last Effect.all references in piping flows, but the
// diagnostic alone cannot offer the data-first quick fix.
export const pipeDataLast = pipe(values.map(effectful), Effect.all)
export const pipeDataLastAsVoid = pipe(values.map(effectful), Effect.all, Effect.asVoid)

// Should not trigger for legitimate Effect.all inputs.
export const tuple = Effect.all([Effect.succeed(1), Effect.succeed("two")] as const)

