const effectUnkown = Effect.context<unknown>()
const layerUnknown = Layer.effectDiscard(effectUnkown)
export const composedLayerUnknown = Layer.empty.pipe(Layer.provide(layerUnknown))

declare const anyFailure: Effect.Effect<number, any>
export const keepsDifferentKind = Effect.withFiber<number, unknown>(() => anyFailure)

declare const anyEverywhere: Effect.Effect<number, any, any>
export const dropsCoveredOuter = Effect.orDie(anyEverywhere)

// @effect-v4

/** @stability unstable */
export interface UnstableType {
  value: string
}

/** @stability experimental */
export interface ExperimentalType {
  value: string
}

/** @stability unstable */
export type UnstableAlias = { value: string }

/** @stability experimental */
export type ExperimentalAlias = { value: string }

// A stable export must not expose unstable or experimental types.
export interface StableExposesUnstable {
  member: UnstableType
}

export interface StableExposesExperimental {
  member: ExperimentalType
}

export function stableFunction(input: ExperimentalType): UnstableType {
  return input as unknown as UnstableType
}

// Public methods and constructors participate in the surface.
export interface StableMethods {
  method(input: ExperimentalType): UnstableType
  new (value: ExperimentalType): StableMethods
}

// Generic target/alias symbols and their type arguments participate too.
export interface Container<T> {
  value: T
}

export type StableWithUnstableArgument = Container<UnstableType>
export type StableWithExperimentalArgument = Container<ExperimentalType>

// Union and intersection constituents are directly represented.
export type StableUnion = UnstableType | string
export type StableIntersection = { tag: string } & ExperimentalType

// Only public class members participate; private and protected members do not.
export class StableClass {
  private secret: ExperimentalType | undefined
  protected guarded: UnstableType | undefined
  public exposed: UnstableType | undefined
}

// An unstable export must not expose experimental types.
/** @stability unstable */
export interface UnstableExposesExperimental {
  member: ExperimentalType
}

// An unstable export may still expose unstable types.
/** @stability unstable */
export interface UnstableExposesUnstable {
  member: UnstableType
}

/** @stability unstable */
export type UnstableWithExperimentalArgument = Container<ExperimentalType>

// An experimental export imposes no restriction.
/** @stability experimental */
export interface ExperimentalExposesEverything {
  unstable: UnstableType
  experimental: ExperimentalType
}

// Inline anonymous object surfaces are directly represented.
export declare function inlineParameter(x: { value: ExperimentalType }): void
export declare function inlineResult(): { value: UnstableType }
export interface InlineNested {
  nested: { value: ExperimentalType }
}
export type InlineCombined = { value: UnstableType } & { other: string }

// An erased alias keeps its tagged symbol even when the checker exposes string.
/** @stability experimental */
export type ExperimentalText = string
export declare function erasedAlias(x: ExperimentalText): ExperimentalText

// Type parameter constraints and defaults are directly represented.
export declare function constrained<T extends UnstableType>(x: T): T
export declare function defaulted<T = ExperimentalType>(): T
export interface GenericConstrained<T extends ExperimentalType> {
  value: T
}
export type IndexedAccess<K extends keyof UnstableType> = UnstableType[K]
export type ConditionalType<T> = T extends ExperimentalType ? ExperimentalType : string

// Traversal follows the declaration graph, not a fixed depth or member count.
interface Box<T> {
  value: T
}
export declare const deepGeneric: Box<Box<Box<Box<Box<ExperimentalType>>>>>
export interface OrderSensitive {
  deep: Box<Box<Box<Box<UnstableType>>>>
  direct: Box<ExperimentalType>
}

// Accessibility is declaration based: `__` is public, private identifiers and
// private constructors are not.
export interface PublicDoubleUnderscore {
  __public: ExperimentalType
}
export class PrivateIdentifierHidden {
  #secret: ExperimentalType | undefined
}
export class PrivateConstructor {
  private constructor(value: ExperimentalType) {}
}

// Callable surfaces expose their call signatures.
interface Callable {
  (value: ExperimentalType): void
}
export interface CallableOwner {
  value: Callable
}
export interface InlineCallable {
  value: (value: UnstableType) => void
}

import { Effect } from "effect"

// Should trigger - async function declaration
export async function declaredAsync() {
  await Promise.resolve(1)
  return 1
}

// Should trigger - async arrow function
export const asyncArrow = async () => {
  await Promise.resolve(2)
  return 2
}

// Should trigger - async method
export const asyncMethod = {
  async run() {
    await Promise.resolve(3)
    return 3
  }
}

// Should trigger - async function inside Effect.gen
export const asyncInGen = Effect.gen(function*() {
  return async function nested() {
    await Promise.resolve(4)
    return 4
  }
})

// Should NOT trigger - regular function using Effect with a real parameter
export const regularFunction = (n: number) => Effect.succeed(n)

import { Effect as Fx, pipe } from "effect"

class NotFoundError {
  readonly _tag = "NotFoundError"
  constructor(readonly id: string) {}
}

class TimeoutError {
  readonly _tag = "TimeoutError"
  constructor(readonly ms: number) {}
}

class AuthError {
  readonly _tag = "AuthError"
}

class DashedError {
  readonly _tag = "dashed-error"
}

declare const program: Fx.Effect<string, NotFoundError | TimeoutError | AuthError>
declare const dashedProgram: Fx.Effect<string, NotFoundError | DashedError | AuthError>

// Should trigger and offer catchTag.
export const ternary = program.pipe(
  Fx.catch((error) =>
    error._tag === "NotFoundError"
      ? Fx.succeed(error.id)
      : Fx.fail(error)
  )
)

// Should trigger and offer catchTags in data-first form.
export const switchMultiple = Fx.catch(program, (error) => {
  switch (error._tag) {
    case "NotFoundError":
      return Fx.succeed(error.id)
    case "TimeoutError":
      return Fx.succeed(String(error.ms))
    default:
      return Fx.fail(error)
  }
})

// Should trigger in pipe(...) style.
export const sequentialIf = pipe(
  program,
  Fx.catch((error) => {
    if (error._tag === "NotFoundError") return Fx.succeed("missing")
    if ("TimeoutError" === error._tag) return Fx.succeed("timeout")
    return Fx.fail(error)
  })
)

// Should preserve quotes when a tag is not a valid identifier property name.
export const nonIdentifierTag = dashedProgram.pipe(
  Fx.catch((error) => {
    switch (error._tag) {
      case "NotFoundError":
        return Fx.succeed("missing")
      case "dashed-error":
        return Fx.succeed("dashed")
      default:
        return Fx.fail(error)
    }
  })
)

// Should NOT trigger: compound conditions do more than tag dispatch.
export const compound = program.pipe(
  Fx.catch((error) =>
    error._tag === "NotFoundError" && error.id === "special"
      ? Fx.succeed("special")
      : Fx.fail(error)
  )
)

// Should NOT trigger: the fallback changes the error.
export const wrappedFallback = program.pipe(
  Fx.catch((error) =>
    error._tag === "NotFoundError"
      ? Fx.succeed("missing")
      : Fx.fail(new AuthError())
  )
)

// Should NOT trigger: dispatch on a nested tag belongs to another rule.
declare const nested: Fx.Effect<string, {
  readonly _tag: "OuterError"
  readonly reason: NotFoundError | TimeoutError
}>

export const nestedTag = nested.pipe(
  Fx.catch((error) =>
    error.reason._tag === "NotFoundError"
      ? Fx.succeed("missing")
      : Fx.fail(error)
  )
)

// Should NOT trigger: every union member must have a literal _tag.
declare const untagged: Fx.Effect<string, NotFoundError | Error>

export const mixedUnion = untagged.pipe(
  Fx.catch((error) =>
    "_tag" in error && error._tag === "NotFoundError"
      ? Fx.succeed("missing")
      : Fx.fail(error)
  )
)

// Should trigger with a fallback fix: catch is hidden behind a const alias.
const catchAlias = Fx.catch
export const aliasedCatch = program.pipe(
  catchAlias((error) => error._tag === "NotFoundError" ? Fx.succeed("missing") : Fx.fail(error))
)

import { Effect, pipe } from "effect"

class MyErrorTagged {
  readonly _tag = "MyErrorTagged"
  constructor(readonly cause: unknown) {}
}

class AnotherError {
  readonly _tag = "AnotherError"
  constructor(readonly message: string) {}
}

// Should trigger: catchAll with arrow function returning Effect.fail
export const shouldTriggerArrow = Effect.fail("error").pipe(
  Effect.catch((cause) => Effect.fail(new MyErrorTagged(cause)))
)

// Should trigger: catchAll with arrow function returning Effect.fail (block body)
export const shouldTriggerArrowBlock = Effect.fail("error").pipe(
  Effect.catch((cause) => {
    return Effect.fail(new MyErrorTagged(cause))
  })
)

// Should trigger: pipe style
export const shouldTriggerPipe = pipe(
  Effect.fail("error"),
  Effect.catch((cause) => Effect.fail(new MyErrorTagged(cause)))
)

// Should trigger: with function expression
export const shouldTriggerFunctionExpr = Effect.fail("error").pipe(
  Effect.catch(function(cause) {
    return Effect.fail(new MyErrorTagged(cause))
  })
)

// Should NOT trigger: catchAll with logic other than just Effect.fail
export const shouldNotTriggerWithLogic = Effect.fail("error").pipe(
  Effect.catch((cause) => {
    console.log(cause)
    return Effect.fail(new MyErrorTagged(cause))
  })
)

// Should NOT trigger: catchAll returning Effect.succeed
export const shouldNotTriggerSucceed = Effect.fail("error").pipe(
  Effect.catch(() => Effect.succeed(42))
)

// Should NOT trigger: catchAll with Effect.flatMap or other operations
export const shouldNotTriggerChained = Effect.fail("error").pipe(
  Effect.catch((cause) =>
    Effect.fail(new MyErrorTagged(cause)).pipe(
      Effect.tap(() => Effect.void)
    )
  )
)

// Should trigger: simple error wrapping
export const shouldTriggerSimple = Effect.fail("original").pipe(
  Effect.catch((e) => Effect.fail(new AnotherError(String(e))))
)

// Should trigger with a fallback fix: the catch API is hidden behind a const alias.
const catchAlias = Effect.catch
export const shouldTriggerAliasedCatch = Effect.fail("error").pipe(
  catchAlias((cause) => Effect.fail(new MyErrorTagged(cause)))
)

import { Effect, pipe } from "effect"

declare const first: Effect.Effect<string, Error>
declare const second: Effect.Effect<number, TypeError>
declare const third: Effect.Effect<boolean, Error>
declare const anyError: Effect.Effect<string, any>

// Should report: all earlier errors are included in the final Error type.
export const pipeable = first.pipe(
  Effect.catch(() => second),
  Effect.catch(() => third)
)

// Should report in free pipe form and accept a single-return block.
export const freePipe = pipe(
  first,
  Effect.catch(() => second),
  Effect.catch(() => {
    return third
  })
)

// Should report for nested data-first calls.
export const dataFirst = Effect.catch(
  Effect.catch(first, () => second),
  () => third
)

// Should not report: a single catch is not a fallback chain.
export const single = first.pipe(Effect.catch(() => second))

// Should not report: the handler depends on the previous error.
export const usesError = first.pipe(
  Effect.catch((error) => Effect.fail(error.message)),
  Effect.catch(() => third)
)

// Should not report: side logic makes the handler more than a lazy expression.
export const sideLogic = first.pipe(
  Effect.catch(() => {
    console.log("fallback")
    return second
  }),
  Effect.catch(() => third)
)

// Should not report: the firstSuccessOf error would be Error | string,
// while the catch chain retains only string.
export const widensError = first.pipe(
  Effect.catch(() => second),
  Effect.catch(() => Effect.fail("last" as const))
)

// Should not report: any passes assignability checks but would absorb the union.
export const anyErrorChannel = anyError.pipe(
  Effect.catch(() => second),
  Effect.catch(() => Effect.fail("last" as const))
)

// Should report: use the handler's annotated return type, not its body type.
export const annotatedReturn = first.pipe(
  Effect.catch((): Effect.Effect<number, Error> => second),
  Effect.catch(() => third)
)

// Should not report: another transformation interrupts the catch run.
export const interrupted = first.pipe(
  Effect.catch(() => second),
  Effect.map(String),
  Effect.catch(() => third)
)

import { Effect } from "effect"

type Todo = {
  readonly id: number
}

declare const encodeTodos: (todos: ReadonlyArray<Todo>) => Effect.Effect<string, unknown>
declare const makeDirectory: (path: string) => Effect.Effect<void, unknown>
declare const writeFile: (path: string, body: string) => Effect.Effect<void, unknown>

class TodosRepoError {
  constructor(readonly args: { cause: unknown } & Record<string, unknown>) {}
}

const filePath = "todos.json"

export const shouldReport = Effect.fn("TodosRepo.writeTodos")(function*(todos: ReadonlyArray<Todo>) {
  const encoded = yield* encodeTodos(todos).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause }))
  )

  yield* makeDirectory(filePath).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause }))
  )

  yield* writeFile(filePath, `${encoded}\n`).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause }))
  )
})

export const shouldNotReportDifferentMapper = Effect.gen(function*() {
  yield* makeDirectory(filePath).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause }))
  )

  yield* writeFile(filePath, "body").pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause, filePath }))
  )
})

export const shouldNotReportLocalCapture = Effect.gen(function*() {
  const suffix = "!"

  yield* makeDirectory(filePath).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause, captured: suffix }))
  )

  yield* writeFile(filePath, suffix).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause, captured: suffix }))
  )
})

export const shouldNotReportMissingMapError = Effect.gen(function*() {
  yield* makeDirectory(filePath).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause }))
  )

  yield* writeFile(filePath, "body")
})

export const shouldReportMixedStyles = Effect.gen(function*() {
  yield* makeDirectory(filePath).pipe(
    Effect.mapError((cause) => new TodosRepoError({ cause }))
  )

  yield* Effect.mapError(writeFile(filePath, "body"), (cause) => new TodosRepoError({ cause }))
})

